// Presentation only: existing notice nodes. No game imports, focus, timers, RAF or event producers.
const instances=new WeakMap(),finite=Number.isFinite;
const box=r=>r&&[r.left,r.top,r.right,r.bottom,r.width,r.height].every(finite)&&r.width>0&&r.height>0?r:null;
export function planCaveNoticeLane({width,height,controls=[],obstacles=[],toastHeight=0,messageHeight=0,toastVisible=false,messageVisible=false,gap=12,left=12,laneWidth=Math.min(300,width-24)}={}){
 if(!finite(width)||!finite(height)||width<=24||height<=24||!finite(toastHeight)||!finite(messageHeight)||toastHeight<0||messageHeight<0)return null;
 const hardEnd=Math.max(0,Math.min(height-gap,...controls.map(box).filter(Boolean).map(r=>r.top-gap))),total=(toastVisible?toastHeight:0)+(messageVisible?messageHeight:0)+(toastVisible&&messageVisible?gap:0),blocked=obstacles.map(box).filter(r=>r&&r.right>left&&r.left<left+laneWidth&&r.bottom>gap&&r.top<hardEnd).map(r=>[Math.max(gap,r.top-gap),Math.min(hardEnd,r.bottom+gap)]).sort((a,b)=>a[0]-b[0]),free=[];
 let cursor=gap;for(const [a,b]of blocked){if(a>cursor)free.push([cursor,a]);cursor=Math.max(cursor,b);}if(cursor<hardEnd)free.push([cursor,hardEnd]);const chosen=[...free].reverse().find(([a,b])=>b-a>=total),end=chosen?chosen[1]:hardEnd,base=Math.ceil((height-end)*100)/100;
 return Object.freeze({left,laneWidth,toastBottom:base,messageBottom:base+(toastVisible?toastHeight+gap:0),hardEnd,stackTop:end-total,stackBottom:end,totalHeight:total,fit:chosen?'free-gap':'constrained',protectsControls:end<=hardEnd,physical:false});
}
export function installCaveNoticeLayout(doc=globalThis.document){
 if(!doc?.body||!doc.defaultView)return null;if(instances.has(doc))return instances.get(doc);const win=doc.defaultView,toast=doc.getElementById('toast'),message=doc.getElementById('message');if(!toast||!message)return null;
 const controls=['controlDeck','itemBar','inspectSkills'].map(id=>doc.getElementById(id)).filter(Boolean),obstacles=['depthLift','objective','explorationHud','missionHud','breathHud','targetTip','frenzyHud','scoreHud','runCards','boostHud'].map(id=>doc.getElementById(id)).filter(Boolean),cleanups=[],saved=[[toast,'--gv-cave-toast-bottom'],[message,'--gv-cave-message-bottom']].map(([node,key])=>({node,key,value:node.style.getPropertyValue(key)})),oldFit=toast.getAttribute('data-gv-notice-fit');let queued=false,disposed=false,last=null;
 const watched=new Set([doc.body,toast,message,...controls,...obstacles]);for(const node of [...watched])for(let p=node.parentElement;p;p=p.parentElement)watched.add(p);
 const cacheable=typeof win.ResizeObserver==='function'&&typeof win.MutationObserver==='function';let dirty=true,lastSignature=null;
 const signature=()=>JSON.stringify([win.innerWidth,win.innerHeight,toast.textContent,message.textContent,...[...watched].map(n=>[n.isConnected,n.hidden,n.inert,n.className,...['style','data-hud-layout-hidden','data-hud-adjusted'].map(k=>n.getAttribute?.(k))])]);
 const attr=(node,key,value)=>{if(value===null){if(node.hasAttribute(key))node.removeAttribute(key);}else if(node.getAttribute(key)!==value)node.setAttribute(key,value);};
 const style=(node,key,value)=>{if(value){if(node.style.getPropertyValue(key)!==value)node.style.setProperty(key,value);}else if(node.style.getPropertyValue(key))node.style.removeProperty(key);};
 function reset(){for(const x of saved)style(x.node,x.key,x.value);attr(toast,'data-gv-notice-fit',oldFit);last=null;}
 function visible(node){if(!node?.isConnected||node.hidden||node.inert||node.closest('[hidden],[inert]'))return false;const s=win.getComputedStyle?.(node);return s?.display!=='none'&&s?.visibility!=='hidden';}
 function sync(){if(disposed)return null;if(cacheable&&!dirty&&lastSignature===signature())return last;dirty=false;if(!doc.body.classList.contains('immersive-run')){reset();if(cacheable)lastSignature=signature();return null;}try{const toastVisible=toast.classList.contains('show')&&visible(toast),messageVisible=!!message.textContent.trim()&&visible(message);if(!toastVisible&&!messageVisible){reset();return null;}const t=box(toast.getBoundingClientRect?.()),m=box(message.getBoundingClientRect?.());if(toastVisible&&!t||messageVisible&&!m){reset();attr(toast,'data-gv-notice-fit','unmeasured');return null;}const plan=planCaveNoticeLane({width:win.innerWidth,height:win.innerHeight,controls:controls.filter(visible).map(n=>n.getBoundingClientRect?.()),obstacles:obstacles.filter(visible).map(n=>n.getBoundingClientRect?.()),toastHeight:t?.height||0,messageHeight:m?.height||0,toastVisible,messageVisible});if(!plan){reset();attr(toast,'data-gv-notice-fit','unmeasured');return null;}style(toast,'--gv-cave-toast-bottom',plan.toastBottom+'px');style(message,'--gv-cave-message-bottom',plan.messageBottom+'px');attr(toast,'data-gv-notice-fit',plan.fit);last=plan;return plan;}catch{reset();attr(toast,'data-gv-notice-fit','unmeasured');return null;}finally{if(cacheable)lastSignature=signature();}}
 function schedule(force=false){if(disposed)return;if(force)dirty=true;if(queued)return;queued=true;(win.queueMicrotask?.bind(win)||((fn)=>Promise.resolve().then(fn)))(()=>{queued=false;sync();});}
 const listen=(node,type,fn)=>{node?.addEventListener?.(type,fn);cleanups.push(()=>node?.removeEventListener?.(type,fn));};listen(win,'resize',schedule);listen(win.visualViewport,'resize',schedule);listen(doc.fonts,'loadingdone',schedule);
 const motionEnd=e=>{if(watched.has(e.target))schedule(true);};for(const type of ['transitionend','transitioncancel','animationend'])listen(doc,type,motionEnd);
 const Resize=win.ResizeObserver;if(typeof Resize==='function'){const observer=new Resize(()=>schedule(true));for(const node of watched)observer.observe(node);cleanups.push(()=>observer.disconnect());}
 const Mutation=win.MutationObserver;if(typeof Mutation==='function'){const observer=new Mutation(()=>schedule());for(const node of watched)observer.observe(node,{attributes:true,attributeFilter:['class','hidden','inert','style','data-hud-adjusted','data-hud-layout-hidden'],...([toast,message].includes(node)?{childList:true,subtree:true,characterData:true}:{})});cleanups.push(()=>observer.disconnect());}
 const api=Object.freeze({sync,getState:()=>last,dispose(){if(disposed)return;disposed=true;for(const cleanup of cleanups)cleanup();reset();instances.delete(doc);}});instances.set(doc,api);sync();return api;
}
